using System.Threading.Tasks;

class A
{
    async static Task<int> Main()
    {
        System.Console.WriteLine("Task<int>");
        return 0;
    }

    async static Task<float> Main(string[] args)
    {
        System.Console.WriteLine("Task<float>");
        return 0.0F;
    }
}

